<script setup lang="ts">
import { ref } from 'vue'
import { api } from '../../api'
import { usePage,perform,busy } from '../../state'
import { label } from '../../domain'
import type { Row } from '../../domain'
import PageHeader from '../../components/PageHeader.vue'
import DataTable from '../../components/DataTable.vue'
import LoadState from '../../components/LoadState.vue'
const tab=ref('jobs'),jobs=ref<Row[]>([]),orders=ref<Row[]>([]),positions=ref<Row[]>([]),payouts=ref<Row[]>([]),plans=ref<Row[]>([]),date=ref('2026-10-12'),type=ref('ALL'),result=ref<Row|null>(null),detail=ref<Row|null>(null),detailOpen=ref(false)
const {loading,error,load}=usePage(async()=>{[jobs.value,orders.value,positions.value,payouts.value,plans.value]=await Promise.all([api.get('/admin/jobs'),api.get('/admin/orders'),api.get('/admin/positions'),api.get('/admin/payouts'),api.get('/sip-plans')])})
async function run(){await perform(async()=>{result.value=await api.post('/admin/jobs',{type:type.value,date:date.value});return result.value},load)}
function inspect(row:Row){detail.value=row;detailOpen.value=true}
</script>
<template><PageHeader title="交易与任务" subtitle="TA模拟确认、资金支付、定投与收益任务共用同一处理流程。"><button class="button" @click="load">刷新</button></PageHeader><LoadState :loading="loading" :error="error" @retry="load"/><div class="tabs"><button v-for="t in [['jobs','任务中心'],['orders','交易订单'],['positions','持仓'],['payouts','待支付与路由'],['plans','定投计划']]" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{ t[1] }}</button></div><template v-if="tab==='jobs'"><section class="panel"><h2>按业务日期执行任务</h2><p class="notice">手动执行仍检查业务时间与适用数据，重复运行由服务端去重。未到时间、缺净值、收款受阻时保留等待状态；不会强行跳过。</p><form class="inline-form" @submit.prevent="run"><label><span>任务类型</span><select v-model="type"><option v-for="t in ['ALL','CONFIRM','PAY','SIP','MONEY','MARKET']" :key="t" :value="t">{{ t==='MONEY'?'货币收益结转':label(t) }}</option></select></label><label><span>业务日期</span><input v-model="date" type="date" required/></label><button class="button primary" :disabled="busy>0">{{ busy?'任务运行中…':'执行任务' }}</button></form><p v-if="type==='MONEY'||type==='ALL'" class="muted small" style="margin-top:14px">货币收益按所选业务日期的前一自然日结转。例如选择10月15日，会处理10月14日收益。</p><div v-if="result" style="margin-top:22px"><span class="inline-tag">成功 {{ result.processed }}</span><span class="inline-tag">等待 {{ result.waiting }}</span><span class="inline-tag">失败 {{ result.failed }}</span><pre v-if="result.details" class="admin-detail">{{ JSON.stringify(result.details,null,2) }}</pre></div></section><section class="panel"><h2>任务历史</h2><DataTable :rows="jobs" :columns="[{key:'id',label:'任务ID'}, {key:'type',label:'类型'}, {key:'date',label:'业务日期'}, {key:'processed',label:'成功'}, {key:'waiting',label:'等待'}, {key:'failed',label:'失败'}, {key:'createdAt',label:'运行时间',kind:'date'}]"><template #actions="{row}"><button class="text-button" @click="inspect(row)">结果详情</button></template></DataTable></section></template><section v-else-if="tab==='orders'" class="panel"><DataTable :rows="orders" :columns="[{key:'orderNo',label:'订单'}, {key:'userId',label:'客户'}, {key:'fundName',label:'基金'}, {key:'type',label:'业务'}, {key:'tradingAccountId',label:'来源账户'}, {key:'sourceCardId',label:'历史来源卡'}, {key:'status',label:'状态',kind:'state'}, {key:'amount',label:'金额（元）',kind:'money'}, {key:'shares',label:'份额',kind:'shares'}, {key:'applicationDate',label:'交易日'}, {key:'reason',label:'原因'}]"><template #actions="{row}"><button class="text-button" @click="inspect(row)">详情</button></template></DataTable></section><section v-else-if="tab==='positions'" class="panel"><DataTable :rows="positions" :columns="[{key:'userId',label:'客户'}, {key:'tradingAccountId',label:'交易账户'}, {key:'fundName',label:'基金'}, {key:'availableShares',label:'可用份额',kind:'shares'}, {key:'shares',label:'份额',kind:'shares'}, {key:'frozenShares',label:'冻结份额',kind:'shares'}, {key:'cost',label:'成本（元）',kind:'money'}, {key:'marketValue',label:'市值（元）',kind:'money'}]"><template #actions="{row}"><button class="text-button" @click="inspect(row)">持仓明细</button></template></DataTable></section><section v-else-if="tab==='payouts'" class="panel"><p class="notice">历史来源卡与实际支付目标分别保留。受阻款项在客户资产中保持应收，不因换卡或持仓核销而消失。</p><DataTable :rows="payouts" :columns="[{key:'id',label:'付款ID'}, {key:'userId',label:'客户'}, {key:'tradingAccountId',label:'交易账户'}, {key:'sourceType',label:'来源业务'}, {key:'sourceCardId',label:'历史来源卡'}, {key:'targetCardId',label:'当前付款目标'}, {key:'amount',label:'金额（元）',kind:'money'}, {key:'dueDate',label:'计划支付日'}, {key:'status',label:'状态',kind:'state'}, {key:'reason',label:'阻塞原因'}]"><template #actions="{row}"><button class="text-button" @click="inspect(row)">支付路径</button></template></DataTable></section><section v-else class="panel"><DataTable :rows="plans" :columns="[{key:'id',label:'计划'}, {key:'userId',label:'客户'}, {key:'fundName',label:'基金'}, {key:'tradingAccountId',label:'固定扣款账户'}, {key:'bankCardId',label:'扣款卡'}, {key:'bindingVersion',label:'版本'}, {key:'amount',label:'金额（元）',kind:'money'}, {key:'frequency',label:'频率'}, {key:'day',label:'日期'}, {key:'status',label:'状态',kind:'state'}]"/></section><el-dialog v-model="detailOpen" title="业务记录明细" width="760px"><pre class="admin-detail">{{ JSON.stringify(detail,null,2) }}</pre></el-dialog></template>
